# typed: strict
# frozen_string_literal: true

# Generated by scripts/formula.ts in tab0inc/happen for each release; edits here are overwritten.
class Happen < Formula
  desc "Message channel between you and a supervising Claude Code session"
  homepage "https://github.com/tab0inc/happen-releases"
  license :cannot_represent

  depends_on :macos

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.5.0/happen_0.5.0_darwin_arm64.tar.gz"
      sha256 "50c2b953ed844b1e8b1953863904012ef578f0cc8f691682119ce8d420cf36f0"
    else
      url "https://github.com/tab0inc/happen-releases/releases/download/v0.5.0/happen_0.5.0_darwin_amd64.tar.gz"
      sha256 "a3e16870986072fa85729870f2075cf8b66eed3663b840fc5ddd1a674a3b7e01"
    end
  end

  def install
    bin.install "happen"
  end

  def caveats
    <<~EOS
      Set up this Mac, start the server (it also starts at login), and connect a browser:
        happen open
      Start a lead: tell Claude Code to run happen skill --channel <channel>
      and follow it, or type in the session:
        ! happen skill --channel <channel>
    EOS
  end

  service do
    run [opt_bin/"happen", "serve"]
    keep_alive true
    log_path var/"log/happen.log"
    error_log_path var/"log/happen.log"
    environment_variables PATH: std_service_path_env
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/happen version")
  end
end
